SELECT t.siteCode, t.waybill_no waybillNo, t.dest_site_code destSiteCode, t.dest_first_site_code destFirstSiteCode, t.total_weight weight, t.total_vol volume, t.total_piece piece, t.product_type_name productTypeName, t.delivery_type_code deliveryType, t.receive_province_name receiveProvinceName, t.receive_city_name receiveCityName, t.receive_district_name receiveDistrictName, t.receive_street receiveTownName, t.receive_address receiveAddress, t.sign_status signStatus, t.receive_name receiveName, t.ecommerce_source_code sourcePlatform, t.modify_dest_site_code modifyDestSiteCode, t.modify_dest_first_site_code modifiedDestFirstSiteCode, t.unload_scan_time centerUnloadTime, t.load_scan_time centerLoadTime, t.load_delivery_receipt_no loadDeliveryReceiptNo, t.delivery_time deliveryTime, t.delivery_scan_name deliveryScanName, t.reach_scan_time siteReachTime, t.send_site_code sendSiteCode, t.sign_time signTime, t.current_should_sign_time currentShouldSignTime, t.validity_lasted_sign_time latestSignTime, t.sign_validity deliveryValidity, t.cod_fee codFee, t.arrive_fee arriveFee FROM ( SELECT CASE WHEN sign_site_code != '0' THEN sign_site_code WHEN modify_dest_site_code != '0' THEN modify_dest_site_code ELSE dest_site_code END as siteCode, waybill_no, dest_site_code, dest_first_site_code, total_weight, total_vol, total_piece, product_type_name, delivery_type_code, receive_province_name, receive_city_name, receive_district_name, receive_street, receive_address, sign_status, receive_name, ecommerce_source_code, modify_dest_site_code, modify_dest_first_site_code, unload_scan_time, load_scan_time, load_delivery_receipt_no, delivery_time, delivery_scan_name, reach_scan_time, send_site_code, sign_time, current_should_sign_time, validity_lasted_sign_time, sign_validity, cod_fee, arrive_fee, dest_modify_time, real_sign_type, reach_site_code ,ROW_NUMBER() over(partition by waybill_no order by validity_lasted_sign_time desc) rn FROM ods_tx_tx_site_should_sign_detail sd where sd.data_valid = 10 and sd.is_cdc_delete=0 /*开始时间前移11天（用于超时未签收）*/ and validity_lasted_sign_time BETWEEN DATE_ADD('2026-11-01 00:00:00',INTERVAL -11 DAY) and DATE_ADD('2026-11-10 23:59:59',INTERVAL 12 DAY) and ( ( sd.dest_first_site_code = '021300405' and sd.modify_dest_first_site_code in ('0', '021300405') ) ) and ( sd.modify_dest_site_code = '021300405' or ( sd.dest_site_code = '021300405' and sd.modify_dest_site_code = '0' ) ) ) t where rn = 1 and validity_lasted_sign_time <= '2026-11-10 23:59:59' and ( ( /*限制查询时间在查询范围内*/ validity_lasted_sign_time BETWEEN '2026-11-01 00:00:00' and '2026-11-10 23:59:59' and validity_lasted_sign_time >= '2026-11-10 17:34:23' and ( modify_dest_first_site_code in ('0', dest_first_site_code) and sign_status = 10 and delivery_type_code in (15, 20) ) ) or ( validity_lasted_sign_time < '2026-11-10 17:34:23' and validity_lasted_sign_time BETWEEN DATE_ADD('2026-11-01 00:00:00',INTERVAL -11 DAY) and '2026-11-10 23:59:59' and ( modify_dest_first_site_code in ('0', dest_first_site_code) and sign_status = 10 and delivery_type_code in (15, 20) ) ) ) order by t.sendSiteCode, t.waybillNo LIMIT 200
